#include "encounter_scene.hpp"
#include <iostream>
unsigned checks=0;void check(bool b){++checks;if(!b)throw std::runtime_error("midboss2 check="+std::to_string(checks));}
int main(int argc,char**argv){try{if(argc!=2)throw std::runtime_error("assets required");
{soew::Midboss2Core m;unsigned damage=0,score=0,bullets=0;soew::Midboss2Core::Hooks h;h.damage=[&](int,int,int w,int height){check(w==64&&height==58);return damage;};h.score=[&](unsigned n){score+=n;};h.bullet=[&](auto&r){check(r.group==128&&r.pattern==84&&r.speed==30);++bullets;};m.trigger(79);check(!m.active);m.trigger(80);m.update(0,0,h);check(m.phase_frame==1&&m.top[0]==-16);damage=100;for(unsigned f=2;f<320;++f){m.begin_frame(f&1);m.update(f&1,0,h);}check(m.damage_taken==318&&score==0&&!m.dying);damage=63;m.begin_frame(0);m.update(0,0,h);check(m.damage_taken==381&&m.dying&&score==20000);for(unsigned f=0;f<64;++f){m.begin_frame(f&1);m.update(f&1,0,h);}check(!m.present&&m.target_x==-1);m.begin_frame(0);check(!m.active);}
{soew::Midboss2Core m;soew::Midboss2Core::Hooks h;m.trigger(80);for(unsigned f=0;f<1600;++f){m.begin_frame(f&1);m.update(f&1,0,h);}check(!m.dying);m.update(0,0,h);check(m.dying&&m.score_awarded==0);}
for(unsigned shot=0;shot<3;++shot){auto s=soew::EncounterScene::load(argv[1],1,int(shot),1,2,3);s.combat_enabled=s.survival_enabled=s.pickup_enabled=true;s.enable_effects();s.enable_bombing();s.midboss2_enabled=true;s.transitions_enabled=true;std::vector<std::uint32_t> pixels(640*400);bool seen=false;for(unsigned f=0;f<6000&&!s.runtime.scroll.done;++f){s.life.invincibility=200;s.tick(0);if(s.midboss2.active)seen=true;if(f%40==0)s.render(pixels);check(!s.runtime.blocked&&!s.stage2_preview_boundary);}check(seen&&s.midboss2.shot_groups>0&&!s.midboss2.present);std::cout<<"shot="<<shot<<" ticks="<<s.ticks<<" groups="<<s.midboss2.shot_groups<<'\n';}
for(unsigned shot=0;shot<3;++shot){auto s=soew::EncounterScene::load(argv[1],1,int(shot),1,2,3);s.combat_enabled=s.survival_enabled=s.pickup_enabled=true;s.enable_effects();s.enable_bombing();s.midboss2_enabled=true;s.pickups.power=80;for(unsigned f=0;f<5000&&s.midboss2.present;++f){s.life.invincibility=200;s.tick(soew::Shot);}check(!s.midboss2.present&&s.midboss2.score_awarded==20000);}
{auto s=soew::EncounterScene::load(argv[1],1,0,1,2,3);s.combat_enabled=s.survival_enabled=true;s.enable_effects();s.enable_bombing();s.midboss2_enabled=true;s.midboss2.active=true;s.midboss2.phase_frame=319;s.midboss2.damage_taken=380;s.midboss2.top.fill(40);s.life.invincibility=200;s.tick(soew::Bomb);check(s.bomb.active&&s.life.bombs==2);s.tick(0);check(s.midboss2.dying&&s.midboss2.score_awarded==20000);}
std::cout<<"midboss2_checks="<<checks<<" failures=0\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
